function openTour(step=0){if(!saveReady||saveConflict)return;if($('modal').open)$('modal').close();if(tourStep<0)tourOrigin={tab,careerTab,industryTab,chartKind,chartMine};titleVisible=false;tourStep=Math.max(0,Math.min(gameplayTour.length-1,step));renderTitle();const t=gameplayTour[tourStep];if(t.page==='Industry'){industryTab=t.section;if(t.section==='Charts'){chartKind='Songs';chartMine=false}}if(t.page==='Career')careerTab=t.section;tab=t.page;render();renderGameplayTour();}
