function action(a){if(a==='rest'&&(s.energy>=200||s.restWeek===s.week)){toast(s.energy>=200?'You are fully rested.':'You already rested this week. Advance for 200 energy.');return}if(a==='practice'){trainingDetail('writing');return}if(a==='promo'&&s.boost>0){toast('Your campaign is already running for this week.');return}if(a==='rest'){if(!spend(0))return;s.restWeek=s.week;s.energy=Math.min(200,s.energy+40);log('You recovered up to 40 energy. Rest is available once per month.')}if(a==='work'){if(!spend(15))return;changeCash(180);recordIncome('wages',180);log('A shift paid $180. A little more runway.')}if(a==='practice'){if(!spend(10))return;s.skill=clamp(s.skill+4);log('Craft improved by 4. Your next session will benefit.')}if(a==='gig'){if(!spend(20))return;let fans=Math.round(5+level('stagePresence')*.16+level('charisma')*.04),pay=Math.round(25+level('marketability')*.2);changeCash(pay);recordIncome('live',pay);s.fans+=fans;s.careerRecords.openMics++;s.careerRecords.liveGross+=pay;s.careerRecords.liveProfit+=pay;gainXP('stagePresence',30);log('Open mic: '+fans+' new fans, '+money(pay)+' earned, +30 Stage Presence XP.')}if(a==='promo'){if(!s.songs.some(x=>x.released)){toast('Release a song first.');return}if(!spend(10,50))return;s.boost=campaignBoost();log('A $50 campaign adds '+Math.round(s.boost*100)+'% to catalog streams this week.')}render()}
