function newSong(e){e.preventDefault();if(s.draft)return;let f=new FormData(e.target),production=studioPackages[Number(f.get('package'))]||studioPackages[0];if(!spend(10,production.fee))return;s.studioIdea={title:'',mood:f.get('mood'),package:String(f.get('package')||'0')};s.started=true;s.draft={id:Date.now()+Math.random(),title:f.get('songtitle').trim()||generate('song'),mood:f.get('mood'),steps:1,quality:0,feature:null,development:JSON.parse(JSON.stringify(s.development)),songRules:2,genre:s.genre,productionBudget:production.fee,productionBonus:production.quality,variation:rand(-8,8),appeal:rand(-12,12)};scoreSong(s.draft);log('Started writing “'+s.draft.title+'”.');render()}
function progressSong(){let d=s.draft;if(!d||d.steps>=3||!spend(15,d.steps===1?40:30))return;d.steps++;if(d.songRules===2){for(const k of (d.steps===2?['recording','charisma']:['producing','marketability','viralAbility']))d.development[k]={...s.development[k]};scoreSong(d)}else d.quality=clamp(Math.round(d.quality+6+level(d.steps===2?'recording':'producing')*.06));render()}
function finishSong(release,confirmed=false){let d=s.draft;if(!d||d.steps!==3)return;if(release&&!confirmed){modal(`<h2>Publish this single?</h2><p>“${esc(d.title)}” will enter your released catalog. You cannot edit the finished recording afterward. Results arrive when you advance the month.</p><p>$20 · energy · 5 energy</p><div class="controls"><button class="secondary" onclick="$('modal').close()">Keep in studio</button><button class="primary" onclick="$('modal').close();finishSong(true,true)">Release single</button></div>`);return}if(release&&!spend(5,20))return;const song={...d,released:release?s.week:null,streams:0,total:0,peak:null,album:null};s.songs.push(song);s.draft=null;log('“'+song.title+'” '+(release?'is out. Results arrive at the end of this week.':'is ready for your album.'));render();toast(release?'Single released. Advance the month for results.':'Finished track saved.')}
function releaseShelf(id,confirmed=false){let x=s.songs.find(x=>x.id===id);if(!x||x.released)return;if(!confirmed){modal(`<h2>Release “${esc(x.title)}”?</h2><p>This publishes the finished recording. Pay $20, 5 energy. Results arrive at week close.</p><button class="primary" onclick="releaseShelf(${id},true)">Publish single</button>`);return}if(!spend(5,20))return;$('modal').close();x.released=s.week;log('“'+x.title+'” is out.');render()}
function albumForm(){let eligible=s.songs.filter(x=>!x.album);modal(`<div class="eyebrow">Your next era</div><h2>Assemble an album.</h2><form class="form" onsubmit="releaseAlbum(event)"><label>Album title${nameInput('albumtitle','album')}</label>${pricingField()}<p class="fine">Select at least 3 tracks. Existing singles retain their streams; new tracks debut together.</p>${eligible.length>5?`<div class="controls"><button type="button" class="secondary" onclick="selectAlbumTracks(this,true)">Select all ${eligible.length} tracks</button><button type="button" class="secondary" onclick="selectAlbumTracks(this,false)">Clear selection</button></div>`:''}${eligible.length?eligible.map(x=>`<label class="row" style="justify-content:flex-start"><input style="width:20px;margin:0" type="checkbox" name="track" value="${x.id}"><span>${esc(x.title)} <small class="muted">${x.released?'Released single':'Unreleased'}</small></span></label>`).join(''):'<p>Finish some tracks in the studio first.</p>'}<button class="primary" ${eligible.length<3?'disabled':''}>Release album · $100</button><span class="fine">10 energy</span></form>`)}
let pendingAlbum=null;
function releaseAlbum(e,confirmed=false){e?.preventDefault();let f=confirmed?pendingAlbum:new FormData(e.target);if(!f)return;let ids=f.getAll('track').map(Number),tracks=s.songs.filter(x=>ids.includes(x.id)&&!x.album);if(tracks.length<3){toast('Choose at least 3 finished tracks.');return}if(!confirmed){pendingAlbum=f;modal(`<h2>Publish this album?</h2><p>${tracks.length} tracks · ${money(Number(f.get('price'))||10)} download price · $100 release fee · 10 energy. Unreleased tracks debut together, and each chosen song joins this album permanently.</p><button class="primary" onclick="releaseAlbum(null,true)">Publish album</button>`);return}if(!spend(10,100))return;pendingAlbum=null;let a={price:albumPrices.some(p=>p.value===Number(f.get('price')))?Number(f.get('price')):10,sales:0,salesRevenue:0,weeklySales:0,id:Date.now(),title:f.get('albumtitle').trim()||generate('album'),week:s.week,tracks:tracks.map(x=>x.id),criticalReception:Math.round(clamp(tracks.reduce((n,x)=>n+x.quality,0)/tracks.length+rand(-8,8))),cohesion:Math.round(clamp(85-(Math.max(...tracks.map(x=>x.quality))-Math.min(...tracks.map(x=>x.quality)))*.4+(s.expansion.albumRollout&&s.expansion.albumRollout.until>=s.week&&ids.includes(s.expansion.albumRollout.lead)?10:0)))};tracks.forEach(x=>{x.album=a.id;if(!x.released)x.released=s.week;x.albumBoost=s.week});s.albums.push(a);updateCertifications();log('Released “'+a.title+'”, a '+tracks.length+'-track album.');$('modal').close();tab='Career';render()}
