function widerIndustry(){const week=s.chartWeek??Math.max(1,s.week-1);const first=['Luna','Cedar','Apollo','Ruby','Dante','Willow','Elio','Sable','Raven','Nico','Violet','Ocean','Remi','Arden','Flora'];const last=['Echo','Coast','Bloom','Fox','Ray','Moon','King','Waves','Hart','Wren'];return Array.from({length:150},(_,i)=>{let era=Math.floor((week+i%8)/8),swing=.82+.36*(.5+.5*Math.sin(i*2.7+week*.61));return {key:'bg:s:'+i+':'+era,releaseWeek:era*8-i%8,title:titles.song[0][(i+era)%10]+' '+titles.song[1][(Math.floor(i/10)+era*3)%10],artist:first[i%15]+' '+last[Math.floor(i/15)],tier:i<20?'Global star':i<75?'Superstar':'Star',streams:Math.round((100000+12000000*Math.pow(1-i/150,3))*swing),background:true}})}

function chartPosition(track){let i=chart().findIndex(x=>x.you&&x.id===track.id);return i<0?null:i+1}
function migrateCharts(){if(s.chartRulesVersion===2)return;for(const track of s.songs){if(track.peak)track.legacyPeak=track.peak;track.peak=null} s.chartRulesVersion=2;s.chartWeek=Math.max(1,s.week-1);log('Global Top 100 now includes the wider industry. Earlier prototype peaks are kept in your release details.');}

function catalog(){let songs=s.songs.filter(x=>x.released);return head('Your music in the world','Your catalog.',`<span class="pill">${songs.length} songs · ${s.albums.length} albums</span>`)+metricRail([['Weekly plays',compact(s.streams)],['Lifetime plays',compact(s.total)],['Fans',compact(s.fans)],['Reputation',s.reputation+'/100']])+`<div class="grid"><section class="card"><div class="sectionhead"><h2>Discography</h2><button class="secondary" onclick="go('Studio')">New music</button></div>${songs.length?songs.slice().reverse().map(x=>`<div class="track"><span class="recordno">${x.album?'ALB':'SGL'}</span><div><button class="release-link" onclick="releaseDetails('songs',${x.id})">${esc(x.title)}</button>${certBadge(x,'songs')}<span class="fine">${x.feature?'feat. '+guestList(x).map(g=>esc(g.name)).join(', ')+' · ':''}${x.total?outcome(x.factor):'Awaiting debut'}${chartPosition(x)?' · #'+chartPosition(x):x.total?' · Uncharted':''}${x.peak===1?' · Chart topper':x.peak?' · Peak #'+x.peak:''}</span><div class="fine">${esc(x.lifecycle||'Awaiting discovery')} · Quality ${x.quality}/100 · Commercial ${x.commercial??'—'}/100</div><div class="fine">${compact(x.streams)} this week · ${compact(x.total)} total</div>${x.legacyPeak?`<p class="fine">Earlier prototype peak: #${x.legacyPeak} (old chart rules)</p>`:''}${x.breakdown?`<details><summary class="fine">Why this result?</summary><p class="fine">${esc(x.breakdown)}</p></details>`:''}</div>${x.factor?`<span class="badge">${x.factor.toFixed(1)}×</span>`:''}</div>`).join(''):'<div class="empty"><h3>Your first era starts here.</h3><p>Release a single or build an album.</p></div>'}${s.albums.length?'<h2 style="margin-top:24px">Albums</h2>'+s.albums.map(a=>{let ts=s.songs.filter(x=>a.tracks.includes(x.id));return `<div class="row"><div><button class="release-link" onclick="releaseDetails('albums',${a.id})">${esc(a.title)}</button>${certBadge(a,'albums')}<span class="fine">${ts.length} tracks · Week ${a.week} · Cohesion ${a.cohesion??'—'}/100</span><p class="fine">${money(a.price)} download · ${fmt(a.sales)} copies sold · ${money(a.salesRevenue)} gross</p><button class="secondary" onclick="changeAlbumPrice(${a.id})">Change price</button></div><strong>${compact(ts.reduce((n,x)=>n+x.total,0))} total</strong></div>`}).join(''):''}</section><div><section class="card"><h2>Your artist</h2><button class="secondary" onclick="go('Artist')">Profile & save settings</button><hr><h2>Live circuit</h2><p>Progress from local rooms to stadiums. Compare demand, budgets, and ticket revenue before booking.</p><p class="fine">Three shows per run · Upfront budgets and energy vary by skills.</p><button class="secondary" onclick="playTour()" ${s.fans<250?'disabled':''}>Review tour venues</button></section><section class="card"><h2>What counts as a hit?</h2><p>A debut below <strong>0.65×</strong> its expected audience is a flop. At <strong>1.5×</strong> or higher, it’s a hit. Number one on the global song chart earns “chart topper.”</p><p class="fine">A superstar’s flop can still dwarf an unknown artist’s hit. The multiplier measures performance relative to your reach at release.</p></section><section class="card"><h2>Plan your next era</h2><p>Compare promotion budgets or announce a four-week album rollout. Costs and boosts are shown before purchase.</p><button class="secondary" onclick="careerTab='Campaigns';render()">Campaigns & rollouts</button></section></div></div>`}
function relationship(a){return a.relation<=-40?'Beef':a.relation<0?'Tense':a.relation<30?'Unfamiliar':a.relation<60?'Friendly':a.relation<85?'Close':'Inner circle'}
function baseFee(a){let t=tier(a.fans);return Math.round([80,900,5000,25000,140000,650000,2000000][t]*(.65+a.reputation/100)*Math.pow(Math.max(1,a.fans/Math.max(500,thresholds[t])),.18)/10)*10}
function freeEligible(a){return accessible(a)&&a.relation>=(tier(a.fans)>=5?98:90)&&s.reputation>=a.reputation-10}
function quote(a){if(freeEligible(a))return 0;return Math.max(10,Math.round(baseFee(a)*(1-Math.max(-60,a.relation)*.006)*(1-a.discount)/10)*10)}
function featureNeeds(a){let t=tier(a.fans);return {fans:t>=2?thresholds[t-2]:0,rep:Math.max([0,5,15,30,48,65,82][t],Math.round(a.reputation)-25),relation:[0,0,0,15,30,50,70][t]}}
function accessible(a){let n=featureNeeds(a);return a.relation>-40&&s.fans>=n.fans&&s.reputation>=n.rep&&a.relation>=n.relation}
function featureRequirements(a){let n=featureNeeds(a);return `<div class="requirements">${[['Fans',s.fans,n.fans,compact],['Reputation',s.reputation,n.rep,fmt],['Relationship',a.relation,n.relation,fmt]].map(([label,v,min,format])=>`<div><span>${v>=min?'✓':'○'} ${label}</span><strong>${format(v)} / ${format(min)}</strong></div>`).join('')}</div>`}

function profile(id){let a=s.world[id],fee=quote(a),blocked=a.relation<=-40,access=accessible(a);modal(`<div class="eyebrow">${tierNames[tier(a.fans)]} · ${esc(a.genre)}</div><h2>${esc(a.name)}</h2><p>${compact(a.fans)} fans · ${compact(a.catalog.reduce((n,x)=>n+x.streams,0))} weekly streams</p><div class="row"><span>${relationship(a)}</span><strong class="${a.relation<0?'bad':'highlight'}">${a.relation>0?'+':''}${a.relation} / 100</strong></div><p class="fine">Talk builds trust. Support helps faster. Beef damages trust, raises fees, and at −40 shuts collaborations down.</p><div class="controls"><button class="secondary" ${a.lastTalk===s.week?'disabled':''} onclick="social(${id},'talk')">Talk</button><button class="secondary" ${a.lastTalk===s.week?'disabled':''} onclick="social(${id},'support')">Support · $25</button><button class="secondary" ${a.lastTalk===s.week?'disabled':''} onclick="social(${id},'beef')">Start beef</button>${a.relation<0?`<button class="secondary" ${a.lastTalk===s.week?'disabled':''} onclick="social(${id},'apologize')">Apologize</button>`:''}</div><p class="fine">One social interaction per artist per month. Each uses 5 energy.</p><hr style="border:0;border-top:1px solid var(--line);margin:23px 0"><h3>Feature offer</h3><p class="fine">Artist reputation: ${fmt(a.reputation)}/100. Audience and reputation set the base price; friendship and negotiation can reduce it.</p><div class="quote">${fee===0?'On the house':money(fee)}</div><p class="fine">Standard fee ${money(baseFee(a))} · ${a.discount?'Negotiated discount active':'Relationship-adjusted quote'}</p><p>${blocked?'They won’t collaborate while you’re beefing. Repair the relationship first.':!access?'Meet all three requirements below before they will consider your record.':freeEligible(a)?'They trust you enough to waive the fee.':'They’re open to a feature. The price reflects your relationship.'}</p>${featureRequirements(a)}<div class="controls"><button class="secondary" ${blocked||!access||a.lastNegotiate===s.week?'disabled':''} onclick="negotiate(${id})">Negotiate</button><button class="primary" ${blocked||!access||!s.draft||guestList(s.draft).length>=6||guestList(s.draft).some(g=>g.id===id)||s.cash<fee?'disabled':''} onclick="bookFeature(${id})">${fee===0?'Accept free feature':'Book · '+money(fee)}</button></div><p class="fine">${!s.draft?'Start a song in Studio to attach a feature.':guestList(s.draft).length>=6?'Your six guest slots are filled.':'Booking attaches the artist to your current song. Fee is charged immediately; booking uses 5 energy.'} A guest expands reach but does not guarantee a hit.</p><h3 style="margin-top:24px">Recent releases</h3>${a.catalog.slice(-3).reverse().map(x=>`<div class="row"><div><strong>${esc(x.title)}</strong><div class="fine">${x.type} · ${outcome(x.factor)}</div></div><span>${compact(x.streams)} / wk</span></div>`).join('')}`)}
function social(id,kind,confirmed=false){if(kind==='beef'&&!confirmed){modal(`<h2>Call out ${esc(s.world[id].name)}?</h2><p>This costs 5 energy. Relationship falls by 35 and fan loyalty and reputation by 2. Feature fees rise; at −40 they refuse to collaborate.</p><div class="controls"><button class="secondary" onclick="profile(${id})">Keep the peace</button><button class="primary" onclick="social(${id},'beef',true)">Start beef</button></div>`);return}let a=s.world[id];if(a.lastTalk===s.week)return;if(!spend(5,kind==='support'?25:0))return;let delta=kind==='beef'?-35:kind==='apologize'?20:kind==='support'?15:Math.round(rand(7,12));if(delta>0&&kind!=='apologize')delta=Math.max(1,Math.round(delta/(1+Math.max(0,tier(a.fans)-tier(s.fans))*.5))); a.relation=clamp(a.relation+delta,-100,100);a.lastTalk=s.week;if(kind==='beef'){a.discount=0;s.loyalty=clamp(s.loyalty-2);s.reputation=clamp(s.reputation-2);log('You called out '+a.name+'. Relationship fell by 35; loyalty and reputation fell by 2.')}else log((kind==='apologize'?'You apologized to ':kind==='support'?'You supported ':'You talked with ')+a.name+'. Relationship +'+delta+'.');render();profile(id)}
function negotiate(id){let a=s.world[id];if(a.lastNegotiate===s.week||a.relation<=-40||!accessible(a)||!spend(5))return;a.lastNegotiate=s.week;let chance=clamp(35+a.relation*.4+(s.reputation-a.reputation)*.35-Math.max(0,tier(a.fans)-tier(s.fans))*5,10,90);if(Math.random()*100<chance){a.discount=Math.min(.4,a.discount+.15);log(a.name+' agreed to a lower feature fee.');toast('Negotiation landed. Your quote is lower.')}else{a.relation=clamp(a.relation-3,-100,100);log(a.name+' declined the offer. Relationship −3.');toast('They declined. You can try again next week.')}render();profile(id)}
function industry(){let tabs=['Artists','Charts','New releases'];let top=head('A living music scene','The industry.')+`<div class="chips">${tabs.map(x=>`<button class="${industryTab===x?'selected':''}" onclick="industryTab='${x}';render()">${x}</button>`).join('')}</div>`;top+=`<div class="controls"><button class="secondary" onclick="featurePicker()">Explore 2,500+ artists</button></div>`;if(industryTab==='Charts')return top+chartHub();if(industryTab==='New releases')return top+`<section class="card"><h2>This week in music</h2>${s.feed.length?s.feed.slice(0,30).map(x=>`<div class="track"><span class="recordno">${x.type==='Album'?'ALB':'SGL'}</span><div><h3>${esc(x.title)}</h3><span class="fine">${esc(x.name)} · ${x.tier} · Week ${x.week}</span><p class="fine">${compact(x.streams)} debut streams · ${x.result}</p></div></div>`).join(''):'<p>The next releases arrive when you advance the month.</p>'}</section>`;return top+`<div class="chips">${['All',...tierNames].map(x=>`<button class="${filter===x?'selected':''}" onclick="filter='${x}';render()">${x}</button>`).join('')}</div><div class="roster-controls"><label>Genre <select onchange="genreFilter=this.value;render()">${['All',...genres].map(g=>`<option ${g===genreFilter?'selected':''}>${g}</option>`).join('')}</select></label><span class="fine">${s.world.filter(a=>(filter==='All'||tierNames[tier(a.fans)]===filter)&&(genreFilter==='All'||a.genre===genreFilter)).length} artists · Tap to meet</span></div><div class="artistgrid">${s.world.filter(a=>(filter==='All'||tierNames[tier(a.fans)]===filter)&&(genreFilter==='All'||a.genre===genreFilter)).map(a=>`<button class="artistcard" onclick="profile(${a.id})"><div class="initials">${a.name.split(' ').map(x=>x[0]).join('')}</div><span class="tier">${tierNames[tier(a.fans)]}</span><h3>${esc(a.name)}</h3><p>${esc(a.genre)} · ${compact(a.fans)} fans</p><p>${compact(a.catalog.reduce((n,x)=>n+x.streams,0))} streams / week</p><p class="rep-line">Reputation <strong>${fmt(a.reputation)}/100</strong></p><p class="${a.relation<0?'bad':''}">${relationship(a)} · ${a.relation>0?'+':''}${a.relation}</p><span class="feature-price">${a.relation<=-40?'Beef · unavailable':quote(a)?'Feature '+money(quote(a)):'Free feature'}</span><span class="fine">${accessible(a)?'Open to collaborate':'Career requirements apply'}</span></button>`).join('')}</div><section class="card" style="margin-top:20px"><h2>Different leagues. Same industry.</h2><p>Unknown → Emerging → Breakout → Star → Superstar → Global star → Global icon. Icons start at 100 million fans in this fictional world.</p><p class="fine">Stream totals depend on audience size, release quality, reception, promotion, features, and catalog age. Artists release new singles and albums on their own schedules.</p></section>`}
function artist(){return head('Identity & growth',esc(s.name)+'.',`<button class="secondary" onclick="setup()">Edit profile</button>`)+`<button class="training-launch" onclick="go('Training')"><span><strong>Training & stat improvement</strong><small>See your stats, choose an activity, and track your progress</small></span><span>Open training</span></button>`+`<section class="identity-banner"><span class="identity-monogram">${esc(s.name.slice(0,2).toUpperCase())}</span><div><span class="eyebrow">${esc(s.genre)} · ${s.labelBusiness?.company?'Founder, '+esc(s.labelBusiness.company.name):s.expansion.contract?esc(s.expansion.contract.name):'Independent'}</span><h2>${tierNames[tier(s.fans)]}</h2><p>${compact(s.fans)} fans · Reputation ${s.reputation}/100</p></div></section>`+`<div class="grid"><section class="card"><span class="tier">${tierNames[tier(s.fans)]} · ${s.labelBusiness?.company?'Founder, '+esc(s.labelBusiness.company.name):s.expansion.contract?esc(s.expansion.contract.name):'Independent'}</span><h2 style="margin-top:14px">${esc(s.genre)} · ${esc(s.background)}</h2>${[['Reputation',s.reputation],['Fan loyalty',s.loyalty],['Energy',s.energy]].map(([t,n])=>`<div class="sectionhead" style="margin:22px 0 0"><span>${t}</span><strong>${n}/${t==='Energy'?200:100}</strong></div><div class="bar"><i style="width:${t==='Energy'?n/2:n}%"></i></div>`).join('')}</section><section class="card" style="align-self:start"><h2>Your career so far</h2><p class="fine">Reputation grows through quality releases (+1 at quality 60+) and hits (+2). Public beef costs 2 reputation. Fame alone won’t unlock every collaboration.</p>${[['Weeks',s.week],['Released tracks',s.songs.filter(x=>x.released).length],['Albums',s.albums.length],['Lifetime streams',compact(s.total)],['Close relationships',s.world.filter(x=>x.relation>=60).length]].map(([k,v])=>`<div class="row"><span>${k}</span><strong>${v}</strong></div>`).join('')}<p class="fine">Playable simulation. Your career autosaves. Return with this browser to continue. Use Career → Saves to export a backup before switching browsers or clearing cookies. No audio is generated. Economy values are game settings, not real-world income forecasts.</p><div class="settings-actions"><button class="secondary" onclick="betaInfo()">Beta & feedback</button><button class="secondary" onclick="careerTab='Saves';go('Career')">Export, import & recovery</button><button class="secondary" onclick="toggleTheme()">${theme==='dark'?'Use light mode':'Use dark mode'}</button><button class="secondary" onclick="openTour(0)">Replay how to play</button><button class="secondary" onclick="showTitle()">Title screen</button></div><button class="secondary" onclick="resetAsk()">Start a new career</button></section></div>`}
const backgroundStarts={
'Bedroom artist':{craft:35,stage:25,fans:42,marketability:25,viralAbility:25,description:'A stronger foundation in writing, recording, and producing.'},
'Local performer':{craft:25,stage:40,fans:60,marketability:25,viralAbility:25,description:'More stage experience and a small local following.'},
'Online creator':{craft:20,stage:20,fans:120,marketability:40,viralAbility:40,description:'A larger starting audience and stronger promotion and discovery skills.'}
};
function backgroundPreview(name){const b=backgroundStarts[name]||backgroundStarts['Bedroom artist'];return `<p>${b.description}</p><dl class="profile-facts">${[['Writing / Recording / Producing',b.craft+' each'],['Charisma / Touring','25 each'],['Marketability',b.marketability],['Stage Presence',b.stage],['Viral Ability',b.viralAbility],['Starting fans',b.fans]].map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl><p class="fine">Every background starts with $650 and 200 energy. Applied once when you begin.</p>`}
function applyStartingBackground(name){const key=Object.hasOwn(backgroundStarts,name)?name:'Bedroom artist',b=backgroundStarts[key];s.background=key;s.skill=b.craft;s.stage=b.stage;s.fans=b.fans;s.development=initialDevelopment(b.craft,b.stage,25);s.development.marketability.level=b.marketability;s.development.viralAbility.level=b.viralAbility;s.backgroundRules=1}
function setup(){modal(`<div class="eyebrow">Your name on the marquee</div><h2>${s.started?'Your artist.':'Create your artist.'}</h2><form class="form" onsubmit="saveProfile(event)"><label>Stage name${nameInput('artistname','artist',s.name)}</label><label>Genre<select name="genre">${genres.map(x=>`<option ${s.genre===x?'selected':''}>${x}</option>`).join('')}</select></label>${s.started?'':`<label>Background<select name="bg" onchange="$('background-preview').innerHTML=backgroundPreview(this.value)"><option>Bedroom artist</option><option>Local performer</option><option>Online creator</option></select></label><div id="background-preview">${backgroundPreview('Bedroom artist')}</div>`}<button class="primary">${s.started?'Save profile':'Begin your career'}</button></form>`)}
function saveProfile(e){e.preventDefault();if(!saveReady||saveConflict)return;const firstProfile=!s.started;let f=new FormData(e.target);s.name=f.get('artistname').trim()||generate('artist');s.genre=f.get('genre');if(!s.started){applyStartingBackground(f.get('bg'));s.started=true}$('modal').close();render();if(firstProfile)tourOffer()}
function resetAsk(){modal(`<h2>A fresh start?</h2><p>${SANDBOX?'This resets only your sandbox, including its test releases. Your normal career is untouched.':'This erases the current career and all relationships.'}</p><div class="controls"><button class="secondary" onclick="$('modal').close()">Keep playing</button><button class="primary" onclick="newCareer()">New career</button></div>`)}
// Reception varies independently of audience size. A hit is relative to expected reach.
function reception(quality){let r=Math.random(),luck=r<.15?rand(.3,.55):r>.9?rand(1.7,2.4):rand(.8,1.2);return Math.max(.15,luck*(.35+quality*.014))}
function worldWeek(){s.world.forEach(a=>{a.catalog.forEach(x=>{x.streams=Math.max(1,Math.round(x.streams*rand(.82,.96)));x.total+=x.streams});if(s.week>=a.nextRelease){let type=Math.random()<.25?'Album':'Single',factor=reception(a.skill),base=Math.round(a.fans*rand(.55,.85)*(type==='Album'?4:1)),streams=Math.round(base*factor),x={uid:a.nextCatalogId++,title:generate(type==='Album'?'album':'song'),type,week:s.week,base,factor,streams,total:streams};a.catalog.push(x);a.fans+=Math.round(streams*.009);a.reputation=clamp(a.reputation+(factor>=1.5?.4:factor<.65?-.3:0));s.feed.unshift({name:a.name,title:x.title,type,week:s.week,tier:tierNames[tier(a.fans)],streams,result:outcome(factor)});a.nextRelease=s.week+Math.round(rand(4,9));if(type==='Album'){let trackStreams=Math.round(streams*.25);a.catalog.push({uid:a.nextCatalogId++,title:generate('song'),type:'Single',week:s.week,base:Math.round(base*.25),factor,streams:trackStreams,total:trackStreams,fromAlbum:true,albumIndex:a.catalog.length-1});x.streams-=trackStreams;x.total-=trackStreams}}a.weekly=a.catalog.reduce((n,x)=>n+x.streams,0)});s.feed=s.feed.slice(0,60)}
function advanceWeek(confirmed=false){if(!saveReady||saveConflict)return;if(!confirmed){modal(`<h2>Finish the week?</h2><p>You have ${s.energy}/200 energy left. Advancing refills it to 200; unused energy does not stack. Career overhead is ${Math.round(operationRate()*100)}% of music income; a tax reserve may also be set aside.</p><div class="controls"><button class="secondary" onclick="$('modal').close()">Keep playing</button><button class="primary" onclick="$('modal').close();advance(true)">Finish week</button></div>`);return}beginCareerWeek();const overheadRate=operationRate();let count=0,added=0,debut=[];s.songs.filter(x=>x.released).forEach(x=>{let n;if(x.factor===undefined){let guest=x.feature?s.world[x.feature.id]:null;let featureReach=guest?x.feature.fans*(guest.relation<=-40?.004:.018):0;x.base=reach(x);x.factor=reception(x.quality)*(x.songRules===2?(.55+x.commercial*.009):1)*(x.mood.startsWith('Raw')?rand(.65,1.4):directionFor(x).reach)*(1+s.boost)*(x.albumBoost===s.week?1.15:1);x.launchFans=s.fans;n=Math.round(x.base*x.factor);x.debutStreams=n;x.organic=n/(1+s.boost)/(x.albumBoost===s.week?1.15:1);x.breakdown='Expected reach '+compact(x.base)+'; quality '+x.quality+'/100'+(x.songRules===2?'; commercial potential '+x.commercial+'/100':'')+'; '+x.mood.split(' /')[0].toLowerCase()+' direction'+(guest?'; guest '+guest.name:'')+'; promotion '+Math.round(s.boost*100)+'%. Audience reception helped determine the final '+x.factor.toFixed(2)+'× debut. '+(x.factor<.65?'Try improving your craft before your next recording.':x.factor>=1.5?'This release outperformed its expected audience.':'This release performed within the expected range.');s.reputation=clamp(s.reputation+(x.quality>=60?1:0)+(x.factor>=1.5?2:0));debut.push(x);log('“'+x.title+'” debuted with '+compact(n)+' streams: '+outcome(x.factor).toLowerCase()+'.')}else{let guest=x.feature?s.world[x.feature.id]:null;let conflict=guest&&guest.relation<=-40?.8:1;x.organic=Math.max(8,(x.organic??x.streams)*rand(...directionFor(x).decay)+s.fans*.002/Math.sqrt(Math.max(1,s.songs.filter(x=>x.released).length)));n=Math.round(x.organic*(1+s.boost)*conflict*(x.albumBoost===s.week?1.15:1));if(x.songRules===2&&Math.random()<(.005+level('viralAbility')*.00045)*directionFor(x).viral){n=Math.round(n*rand(1.8,3.5));log('“'+x.title+'” caught a viral discovery wave.')} }n=adjustReleaseStreams(x,n);if(x.released===s.week){x.debutStreams=n;x.breakdown+=' Genre fit '+x.marketFit+'%; release spacing '+Math.round(x.rolloutFactor*100)+'%.'}x.streams=n;x.total+=n;count+=n;added+=Math.round(n*directionFor(x).fans*(1+s.loyalty/200)*(x.songRules===2?.75+level('charisma')*.005:1))});settleAlbumSales();worldWeek();settleLabelWeek();s.chartWeek=s.week;for(const a of s.albums)if(a.debutStreams===undefined&&a.week===s.week)a.debutStreams=albumStreams(a);let rankings=compileSongs();updateChartRecords(rankings);rankings.forEach((x,i)=>{if(x.you){let track=s.songs.find(y=>y.id===x.id);track.peak=Math.min(track.peak||Infinity,i+1)}});s.streams=count;s.total+=count;added=settleAudience(count,added);s.fans=Math.max(0,s.fans+added);let royalties=Math.round(count*.50*100)/100;const financial=closeFinances(royalties,overheadRate);s.energy=200;if(added>0)s.loyalty=clamp(s.loyalty+1);s.careerRecords.royalties+=royalties;s.lastReport={cashChange:financial.net,finance:financial,streams:count,fans:added,royalties,debut:debut.map(x=>x.id)};finishCareerWeek();let completed=s.week;const earned=scanAchievements();catalogReport(completed);weeklyNews(completed);s.week++;s.boost=0;log(count?compact(count)+' streams, '+fmt(added)+' net fans, and '+money(royalties)+' in royalties.':'A fresh week. New records are dropping around you.');if(s.cash<0)log('Your balance is below zero. Work shifts can cover the shortfall.');if(!monthlyAdvancing){render();weekRecap(completed,count,added,debut,financial,earned)}}
function nextStep(){let heading,text,button,handler;
if(!s.started){heading='Start with one record';text='Create your artist, then write, record, mix, and release a single. Each week starts with 200 energy.';button='Create artist';handler='setup()'}
else if(s.cash<0){heading='Give yourself some runway';text='A work shift earns $180 before taxes and can help cover career expenses, even when your balance is negative.';button='Work a shift';handler="action('work')"}
else if(s.energy<15){heading='Take a breather';text='Rest restores 40 energy once per month. A new week refills it to 200.';button='Rest';handler="action('rest')"}
else if(s.draft){heading=['','Put down the vocals','Give it a final mix','Your record is ready'][s.draft.steps];text=s.draft.steps===3?'Release it now for $20 or save it for an album.':'You can pause a project and continue next week. Your work stays in the studio.';button='Continue record';handler="go('Studio')"}
else if(!s.songs.some(x=>x.released)){heading='Make your first single';text='Budget $90 and 45 energy to go from idea to release. You can work on it over more than one week.';button='Open studio';handler="go('Studio')"}
else if(s.songs.some(x=>x.released&&x.factor===undefined)){heading='Your debut is on the way';text='Advance the month to see the results. If you still have time, practice, rest, or work a shift.';button='Review releases';handler="go('Career')"}
else if(s.week<=8){heading='Build a rhythm that works';text='Work covers bills. Practice improves future records. Open mics grow your first audience. You don’t need a feature or an album yet.';button='Review your results';handler="go('Career')"}
else return '';
return `<section class="card guide"><div><span class="eyebrow">Your next step</span><h3>${heading}</h3><p>${text}</p></div><button class="secondary" onclick="${handler}">${button}</button></section>`}

function exactCash(n){return Math.abs(n)>=1e6?currencyLabel(n,true):new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(n)}
function homeStats(){let report=s.empire.lastMonth||s.lastReport;return `<section class="home-dashboard" aria-label="Career overview"><div class="overview-numbers">${[
['cash','Cash',s.cash<0?'−$'+compact(-s.cash):'$'+compact(s.cash),s.cash<0?'Balance below zero':'Available to spend',s.cash<0],
['fans','True fans',compact(s.fans),report?(report.fans>=0?'+':'')+fmt(report.fans)+' last month':'Building your audience',false],
['streams','Monthly streams',compact(s.empire.lastMonth?.streams||s.streams),s.empire.lastMonth?'Last completed month':s.week>1?'Latest chart week':'First results pending',false]
].map(([key,label,value,note,low])=>`<button class="overview-stat ${low?'overview-low':''}" onclick="statDetail('${key}')" aria-label="${label}: ${key==='cash'?exactCash(s.cash):fmt(key==='fans'?s.fans:(s.empire.lastMonth?.streams||s.streams))}. View details"><span class="overview-label">${label}</span><strong>${value}</strong><span class="overview-note">${note}</span></button>`).join('')}</div><div class="overview-resources"><button onclick="statDetail('energy')" class="resource-item ${s.energy<20?'overview-low':''}"><span>Energy <strong>${s.energy}/200</strong></span><span class="resource-meter" aria-hidden="true"><i style="width:${s.energy/2}%"></i></span></button><button onclick="statDetail('energy')" class="resource-item"><span>Recovery <strong>${s.restWeek===s.week?'Used':'Available'}</strong></span><small>Rest +40 · once per month</small></button></div><div class="overview-caption">Tap a stat for the full breakdown</div></section>`}
function statDetail(key){let r=s.lastReport;let titles={cash:'Your cash',fans:'Your audience',streams:'Your streams',energy:'Your energy',time:'Your week'};let rows,description;
if(key==='cash'){rows=[['Available balance',exactWallet()],['Tax reserve (separate)',exactCash(s.finance.reserve)],['Last week’s royalties',r?exactCash(r.royalties):'No results yet'],['Current royalty rate','$0.50 per stream'],['Work shift income','$180.00']];description='Available cash includes your actions so far. Royalties are streaming income only, not total weekly profit. Large denominations: M million, B billion, T trillion, Qa quadrillion, Qi quintillion. Cash debits and credits are kept in an exact cents ledger. Large stream totals and calculated revenue are still simulation estimates.'}
if(key==='fans'){rows=[['True fans',fmt(s.fans)],['Net fans from last week’s streams',r?(r.fans>=0?'+':'')+fmt(r.fans):'No results yet'],['Estimated weekly listeners',compact(s.expansion.listeners)],['Fans lost last week',fmt(s.expansion.lastAudience?.churn||0)],['Career tier',tierNames[tier(s.fans)]],['Fan loyalty',s.loyalty+'/100']];description='Fans are people who support your artist. Streams count plays, so one fan can generate more than one stream. Open-mic fans join immediately; the weekly figure is new streaming fans minus audience churn. Release spacing, catalog size, and loyalty affect audience growth.'}
if(key==='streams'){rows=[['Last completed week',s.week>1?'Week '+(s.week-1):'None yet'],['Streams that week',fmt(s.streams)],['Last completed month',fmt(s.empire.lastMonth?.streams||0)],['Lifetime streams',fmt(s.total)],['Released tracks',fmt(s.songs.filter(x=>x.released).length)],['Campaign this week',s.boost>0?'+'+Math.round(s.boost*100)+'% streaming boost':'No campaign']];description='Streams update after you advance the month. These totals combine all your released tracks. Album tracks are counted once.'}
if(key==='energy'||key==='time'){rows=[['Energy available',s.energy+'/200'],['Rest',s.restWeek===s.week?'Used this month':'+40 once per month'],['Advance month','Refills to 200'],['Writing / recording / mixing','−10 / −15 / −15']];description='Actions use energy, with no time-slot limit. Rest is available once per month; advance the month for a full refill and release results.'}
modal(`<div class="eyebrow">Career overview</div><h2>${titles[key]}</h2>${rows.map(([label,value])=>`<div class="row"><span>${label}</span><strong>${value}</strong></div>`).join('')}<p>${description}</p>`)}


function metricRail(items){return `<div class="metric-rail">${items.map(([l,v])=>`<div><span>${l}</span><strong>${v}</strong></div>`).join('')}</div>`}
function saveStatus(message,error=false){let el=$('save-status');el.textContent=message;el.className='save-status'+(error?' error':'')}
function queueSave(){if(monthlyAdvancing)return;if(!saveReady||saveConflict||JSON.stringify(s)===lastSaved)return;checkpointCareer();saveStatus('Unsaved changes');clearTimeout(saveTimer);saveTimer=setTimeout(saveNow,250)}
async function saveNow(){if(OFFLINE)return saveLocal();clearTimeout(saveTimer);if(!saveReady||saveConflict||saveBusy)return;checkpointCareer();const snapshot=JSON.stringify(s);if(snapshot===lastSaved){saveStatus('Career saved ✓');return}saveBusy=true;saveStatus('Saving…');try{let response=await fetch(SAVE_URL,{method:'PUT',headers:{'Content-Type':'application/json',...(saveEtag?{'If-Match':saveEtag}:{'If-None-Match':'*'})},body:JSON.stringify({schemaVersion:1,state:JSON.parse(snapshot)}),keepalive:snapshot.length<55000});if(response.status===409){saveConflict=true;throw Error('A different tab saved this career. Reload to continue.')}if(!response.ok)throw Error('Save failed. Keep this tab open and tap Retry save.');let result=await response.json();saveEtag=result.etag;lastSaved=snapshot;checkpointCareer();saveStatus('Career saved ✓')}catch(e){saveStatus(saveConflict?'Other tab saved · reload':'Retry save',true);toast(e.message)}finally{saveBusy=false;if(!saveConflict&&lastSaved===snapshot&&JSON.stringify(s)!==lastSaved)queueSave()}}
async function boot(){titleVisible=true;renderTitle();if(OFFLINE){await bootLocal();prepareOffline();return}saveStatus('Loading career…');try{let response=await fetch(SAVE_URL,{cache:'no-store'});if(!response.ok)throw Error('Your saved career could not be loaded.');let data=await response.json();if(data.save){if(data.save.schemaVersion!==1)throw Error('This career needs a newer game version. Reload to update.');let loaded=data.save.state;if(!loaded||!Array.isArray(loaded.world)||!Number.isFinite(loaded.week))throw Error('The saved career could not be read.');if(!!loaded.sandbox!==SANDBOX)throw Error('This save belongs to a different game mode.');s=loaded;lastSaved=JSON.stringify(s);migrateCharts();migratePacing();migrateDevelopment();migrateCareerRecords();migrateFinance();migrateChartBook();migrateAchievements()}saveEtag=data.etag;recoverPendingCareer(data);saveReady=true;$('save-status').onclick=saveNow;render();showTitle();if(lastSaved===JSON.stringify(s))saveStatus('Career restored ✓');else await saveNow()}catch(e){saveReady=false;titleVisible=false;renderTitle();saveStatus('Retry loading',true);$('save-status').onclick=boot;$('app').innerHTML=`<section class="card"><h2>Let’s protect your progress.</h2><p>${esc(e.message)} Your existing save has not been replaced.</p><button class="primary" onclick="boot()">Try again</button></section>`}}
async function newCareer(){if(saveBusy){toast('Wait for the current save to finish.');return}if(saveConflict){toast('Reload this tab before starting a new career.');return}if(!backupCareer(true))return;s=fresh();tab='Home';$('modal').close();render();await saveNow();showTitle()}
window.addEventListener('beforeunload',e=>{if(saveReady&&JSON.stringify(s)!==lastSaved){e.preventDefault();e.returnValue=''}});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')saveNow()});
function migratePacing(){migrateEnergy()}
const developmentInfo={writing:['Writing','Lyrics, hooks and song structure.','Freestyle writing','Songwriting session','Intensive workshop'],recording:['Recording','Vocal execution, delivery and studio performance.','Vocal warm-up','Recording session','Vocal masterclass'],producing:['Producing','Beats, arrangement and mixing instincts.','Beat sketch','Production session','Production workshop'],charisma:['Charisma','Interviews, personality and turning listeners into fans.','Interview practice','Fan connection session','Media workshop'],marketability:['Marketability','Turn attention into fans, streams, tickets and opportunities.','Brand exercise','Campaign planning','Artist branding workshop'],stagePresence:['Stage Presence','Improves live fan conversion and performance reviews.','Stage rehearsal','Performance practice','Live masterclass'],touring:['Touring','Reduces local-run energy needs and improves live earnings.','Route planning','Show logistics','Tour management workshop'],viralAbility:['Viral Ability','Strengthens promotion and the chance of catalog discovery waves.','Trend study','Content session','Social campaign workshop']};
const coreStats=['writing','recording','producing','charisma','marketability'];
function initialDevelopment(craft=0,stage=0,other=0){return Object.fromEntries(['writing','recording','producing','charisma','marketability','stagePresence','touring','viralAbility'].map(k=>[k,{level:['writing','recording','producing'].includes(k)?craft:k==='stagePresence'?stage:other,xp:0}]))}
function migrateDevelopment(){if(s.developmentVersion===1)return;s.development=initialDevelopment(s.skill??35,s.stage??25,25);s.developmentVersion=1;log('Artist development unlocked. Your Craft became Writing, Recording and Producing; Stage Presence was preserved. Existing records keep their quality and results.')}
function level(k){return s.development[k].level}
function xpNeeded(n){return Math.round(60+n*3+(n>25?(n-25)*3:0)+(n>50?(n-50)*12:0)+(n>70?(n-70)**2*12:0)+(n>85?(n-85)**3*8:0))}
function difficulty(n){return n<=25?'Easy':n<=50?'Moderate':n<=70?'Hard':n<=85?'Very hard':n<=95?'Elite':'Generational'}
function gainXP(k,amount){let a=s.development[k];if(a.level>=100)return; a.xp+=amount;while(a.level<100&&a.xp>=xpNeeded(a.level)){a.xp-=xpNeeded(a.level);a.level++}if(a.level===100)a.xp=0}
function campaignBoost(){return .2+level('marketability')*.003+level('viralAbility')*.001}
function scoreSong(d){const v=k=>d.development[k].level;let w=directionFor(d).weights;d.quality=Math.round(clamp(coreStats.reduce((n,k,i)=>n+v(k)*w[i],0)+d.variation+Math.min(d.productionBonus||0,3+v('producing')*.08)));d.commercial=Math.round(clamp(d.quality*.55+v('marketability')*.25+v('charisma')*.1+v('viralAbility')*.1+d.appeal+directionFor(d).appeal))}
function statCard(k,sub=false){let a=s.development[k],info=developmentInfo[k];return `<section class="${sub?'substat':'card development-card'}"><div class="sectionhead"><h2>${info[0]}</h2><span class="training-score">${a.level}<small>/100</small></span></div><div class="bar" role="progressbar" aria-label="${info[0]} level" aria-valuenow="${a.level}" aria-valuemin="0" aria-valuemax="100"><i style="width:${a.level}%"></i></div><p>${info[1]}</p><div class="development-footer"><span class="fine">${a.level===100?'Maximum reached':difficulty(a.level)+' · '+fmt(a.xp)+' / '+fmt(xpNeeded(a.level))+' XP'}</span><button class="secondary" onclick="trainingDetail('${k}')">${a.level===100?'View mastery':'Train →'}</button></div>${k==='marketability'?`<details class="market-details"><summary>Performance & discovery · Details</summary><p class="fine">These abilities train independently. They do not replace or automatically increase Marketability.</p>${['stagePresence','touring','viralAbility'].map(x=>statCard(x,true)).join('')}<p class="fine">Festival opportunities and larger venue progression will come with expanded touring.</p></details>`:''}</section>`}
function training(){return head('Artist development','Stats.',`<span class="pill">⚡ ${s.energy}/200</span>`)+`<p class="development-intro">Five independent abilities. Build your sound, your presence, and your audience.</p><div class="development-stack">${coreStats.map(k=>statCard(k)).join('')}<section class="card training-rest"><div><h3>Recover & return</h3><p class="fine">Training uses energy only. Rest restores up to 40 energy once per month; a new week refills it to 200.</p></div><button class="secondary" ${s.energy>=200||s.restWeek===s.week?'disabled':''} onclick="action('rest')">Rest · +${Math.min(40,200-s.energy)} energy</button></section><details class="card"><summary>How development affects your music</summary><p>Standard quality: Writing 30%, Recording 30%, Producing 25%, Charisma 5%, Marketability 10%. Personal songs emphasize Writing; experimental songs emphasize Producing.</p><p>Commercial potential: Quality 55%, Marketability 25%, Charisma 10%, Viral Ability 10%, plus song-specific appeal. Creative execution varies. Audience reception and discovery still decide whether a release catches on.</p><p>Writing is captured when you start; Recording and Charisma at recording; Producing, Marketability and Viral Ability at mixing. Training never rewrites finished records.</p><p>Higher levels cost progressively more XP. Reaching 99–100 takes sustained development over years, even with intensive training.</p></details></div>`}
function trainingDetail(k){if(!developmentInfo[k])return;let a=s.development[k],info=developmentInfo[k];modal(`<div class="eyebrow">Artist development · ${difficulty(a.level)}</div><h2>${info[0]}</h2><div class="training-score">${a.level}<small> / 100</small></div><p>${info[1]}</p><div class="bar"><i style="width:${a.level===100?100:a.xp/xpNeeded(a.level)*100}%"></i></div><p>${a.level===100?'Generational mastery':`Next level: ${a.level} → ${a.level+1} · ${fmt(a.xp)} / ${fmt(xpNeeded(a.level))} XP`}</p><p class="fine">⚡ ${s.energy} energy available · No cash cost</p><div class="training-options">${[5,10,20].map((cost,i)=>`<button class="training-option" ${a.level>=100||s.energy<cost?'disabled':''} onclick="trainStat('${k}',${i})"><strong>${info[i+2]}</strong><span>+${[20,40,80][i]} XP · ⚡ ${cost}</span></button>`).join('')}</div><p class="fine">XP carries toward the next level. Elite levels need substantially more sessions.</p>`)}
function trainStat(k,i){if(!saveReady||saveConflict||!developmentInfo[k]||![0,1,2].includes(i))return;let cost=[5,10,20][i];if(level(k)>=100||s.energy<cost)return;s.started=true;s.energy-=cost;let before=level(k);gainXP(k,[20,40,80][i]);log(developmentInfo[k][0]+': +'+[20,40,80][i]+' XP'+(level(k)>before?' · Level '+level(k):'')+'.');render();trainingDetail(k)}
function tourEnergy(){return Math.round(45-level('touring')*.2)}
function tourGross(){return Math.round(100+Math.min(s.fans,5000)*.035+level('touring')*1.2+level('marketability')*.8)}
function legacyPlayTour(confirmed=false){if(s.fans<250){toast('Build an audience of 250 fans first.');return}let energy=tourEnergy(),gross=tourGross();if(!confirmed){modal(`<h2>Book this local run?</h2><p>Three shows use ${energy} energy. Pay $100 upfront; gross earnings are ${money(gross)}, for ${money(gross-100)} before weekly overhead and income tax.</p><div class="controls"><button class="secondary" onclick="$('modal').close()">Keep planning</button><button class="primary" onclick="$('modal').close();playTour(true)">Confirm local run</button></div>`);return}if(!spend(energy,100))return;changeCash(gross);recordIncome('live',gross);let fans=Math.round(15+level('stagePresence')*.6+level('charisma')*.2);s.fans+=fans;let review=clamp(Math.round(level('stagePresence')*.7+level('charisma')*.3+rand(-10,10)));if(review>=70)s.reputation=clamp(s.reputation+1);s.careerRecords.liveGross+=gross;s.careerRecords.liveProfit+=gross-100;s.careerRecords.tours.push({week:s.week,title:'Local run '+(s.careerRecords.tours.length+1),gross,profit:gross-100,fans,review});gainXP('touring',60);gainXP('stagePresence',40);log('Local run: '+money(gross-100)+' profit, '+fans+' fans, '+review+'/100 live review. +60 Touring XP, +40 Stage Presence XP.');render();toast('Run complete: '+money(gross-100)+' profit · '+fans+' fans · Review '+review+'/100')}

function fresh(){const state=baseFresh();if(!SANDBOX)return state;state.sandbox=true;state.achievements.baselinePending=true;state.started=true;state.name='Solace';state.cash=1000000000;state.fans=200000000;state.energy=200;state.skill=100;state.stage=100;state.reputation=100;state.loyalty=100;Object.values(state.development).forEach(a=>{a.level=100;a.xp=0});state.world.forEach(a=>{a.relation=100});state.history=[{week:1,text:'Sandbox opened: max abilities, $1 billion, 200 million fans and maximum relationships. Separate save from your normal career.'}];state.songs=['The World Is Listening','After the Spotlight','Encore Forever'].map((title,i)=>({id:90001+i,title,mood:['Catchy / radio-ready','Personal / storytelling','Raw / experimental'][i],steps:3,quality:100,commercial:100,songRules:2,released:1,streams:0,total:0,peak:null,album:null,feature:null}));return state}
function sandboxBar(){return SANDBOX?`<aside class="sandbox-banner"><div><strong>ENCORE LAB · SANDBOX</strong><p>Separate test save · Results here never enter your normal career.</p></div><div class="controls"><button class="secondary" onclick="refillSandbox()">Refill resources</button><button class="primary" onclick="sandboxEditor()">Edit sandbox</button><a class="secondary" href="${OFFLINE?'/offline':'/'}">Normal game</a></div></aside>`:''}
function refillSandbox(){if(!SANDBOX||!saveReady||saveConflict)return;changeCash(Math.max(0,1000000000-s.cash));s.energy=200;log('Sandbox resources refilled: cash and energy.');render();toast('Resources refilled. Advance the month whenever you want release results.')}
function migrateCareerRecords(){if(s.careerRecords)return;s.careerRecords={sinceWeek:s.week,tours:[],openMics:0,royalties:0,liveGross:0,liveProfit:0};}

function profileRows(rows){return `<dl class="profile-facts">${rows.map(([label,value])=>`<div><dt>${esc(label)}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl>`}
function careerProfile(){const released=s.songs.filter(x=>x.released),records=s.careerRecords,certifiedSongs=released.filter(x=>certificationUnits(x,'songs')>=500000),certifiedAlbums=s.albums.filter(x=>certificationUnits(x,'albums')>=500000),songOnes=released.filter(x=>x.peak===1),albumOnes=s.albums.filter(x=>x.peak===1),bestSong=released.reduce((best,x)=>!best||x.total>best.total?x:best,null),bestAlbum=s.albums.reduce((best,x)=>!best||albumStreams(x,true)>albumStreams(best,true)?x:best,null),bestTour=records.tours.reduce((best,x)=>!best||x.gross>best.gross?x:best,null),report=s.finance.last,changed=report?.net;
const plaques=[...released.map(x=>({item:x,kind:'songs'})),...s.albums.map(x=>({item:x,kind:'albums'}))].filter(x=>certificationUnits(x.item,x.kind)>=500000).sort((a,b)=>certificationUnits(b.item,b.kind)-certificationUnits(a.item,a.kind));
return `<article class="career-profile editorial-profile"><div class="profile-masthead"><span>ENCORE</span><span>THE CAREER EDITION${SANDBOX?' · LAB':''}</span></div><div class="profile-body"><div class="profile-kicker"><span class="profile-monogram">E</span> THE ARTIST FILE · ${careerDate()}</div><h1>${esc(s.name)}</h1><p class="profile-role">${esc(s.genre)} · ${esc(tierNames[tier(s.fans)])} · ${s.labelBusiness?.company?'Founder, '+esc(s.labelBusiness.company.name):s.expansion.contract?esc(s.expansion.contract.name):'Independent'}</p><div class="wealth-feature"><div><span class="profile-kicker">Spendable cash</span><strong>${money(s.cash)}</strong><p>${changed===undefined?'Your first financial report is ahead.':(changed>=0?'+':'−')+money(Math.abs(changed))+' net in the last completed week'}</p></div><div class="wealth-aside"><span>Tax reserve <b>${money(s.finance.reserve)}</b></span><span>Cash + reserve <b>${money(s.cash+s.finance.reserve)}</b></span><button class="secondary" onclick="careerTab='Finances';go('Career')">Financial report</button></div></div><div class="profile-spotlights">${[['Lifetime streams',compact(s.total)],['True fans',compact(s.fans)],['#1 songs / albums',songOnes.length+' / '+albumOnes.length],['Certified releases',certifiedSongs.length+certifiedAlbums.length]].map(([k,v])=>`<div><span>${k}</span><strong>${v}</strong></div>`).join('')}</div><p class="profile-note">Financial figures reflect this career’s cash and tax reserve, not an estimated catalog valuation or real-world wealth ranking.</p><section class="editorial-section"><div class="sectionhead"><h2>The current chapter</h2><button class="secondary" onclick="industryTab='Charts';go('Industry')">Open charts</button></div>${profileRows([['Chart issue',s.chartBook.issuedWeek?'Week '+s.chartBook.issuedWeek:'First issue pending'],['Songs charting now',chart().filter(x=>x.you).length],['Albums charting now',albumChart().filter(x=>x.you).length],['Last week’s streams',fmt(s.streams)],['Reputation / fan loyalty',s.reputation+' / '+s.loyalty],['Career length',(s.week-1)+' completed weeks'],['Featured appearances',s.expansion.featureAppearances||0],['Award wins / nominations',(s.expansion.awardWins||0)+' / '+(s.expansion.awardNominations||0)],['Estimated weekly listeners',compact(s.expansion.listeners)],['Achievements unlocked',Object.keys(s.achievements.unlocked).length+' / '+achievementDefinitions().length]])}</section><section class="editorial-section"><div class="sectionhead"><h2>The discography</h2><button class="secondary" onclick="careerTab='Releases';go('Career')">All releases</button></div>${profileRows([['Released songs / albums',released.length+' / '+s.albums.length],['Songs with guest artists',released.filter(x=>x.feature).length],['Most-streamed song',bestSong&&bestSong.total?bestSong.title+' · '+compact(bestSong.total)+' streams':'Awaiting release results'],['Most-streamed album',bestAlbum&&albumStreams(bestAlbum,true)?bestAlbum.title+' · '+compact(albumStreams(bestAlbum,true))+' streams':'Awaiting album results'],['Song chart entries',released.filter(x=>x.peak).length],['Album chart entries',s.albums.filter(x=>x.peak).length],['Longest song run at #1',Math.max(0,...released.map(x=>x.longestNumberOne||0))+' weeks'],['Longest album run at #1',Math.max(0,...s.albums.map(x=>x.longestNumberOne||0))+' weeks']])}</section><section class="editorial-section"><div class="sectionhead"><h2>The plaque collection</h2><button class="secondary" onclick="careerTab='Certifications';go('Career')">View awards</button></div><p class="profile-note">${certifiedSongs.length} certified songs · ${certifiedAlbums.length} certified albums. Each release is counted once at its highest award.</p><div class="profile-plaques">${plaques.slice(0,4).map(({item,kind})=>`<button class="profile-plaque" onclick="releaseDetails('${kind}',${item.id})">${certBadge(item,kind)}<strong>${esc(item.title)}</strong><small>${kind==='songs'?'Song':'Album'} · ${compact(certificationUnits(item,kind))} units</small></button>`).join('')||'<p class="profile-note">Your first Gold record belongs here. Follow every release’s progress in Certifications.</p>'}</div></section><section class="editorial-section"><h2>On the road</h2>${profileRows([['Open mics / live runs',records.openMics+' / '+records.tours.length],['Highest-grossing run',bestTour?bestTour.title+' · '+money(bestTour.gross):'No completed runs'],['Best live review',records.tours.length?Math.max(...records.tours.map(x=>x.review))+' / 100':'—'],['Live gross / profit',money(records.liveGross)+' / '+money(records.liveProfit)],['Tracked streaming royalties',money(records.royalties)]])}</section><p class="profile-note">Live and earnings records tracked from Week ${records.sinceWeek}; detailed chart history from Week ${s.chartBook.sinceWeek}. Missing historical debuts are never invented. Certifications use saved lifetime streams and tracked album downloads.</p><div class="profile-footer"><button class="secondary" onclick="setup()">Edit artist</button><button class="secondary" onclick="go('Artist')">Career settings</button>${OFFLINE?'':'<a class="secondary" href="/offline">Play offline edition</a>'}${SANDBOX?`<button class="secondary" onclick="resetAsk()">Reset sandbox</button>`:`<a class="secondary" href="${OFFLINE?'/offline/sandbox':'/sandbox'}">Open sandbox</a>`}</div></div></article>`}

function career(){const nav=careerMenu();const extra={Social:pulsePage,Deals:dealsPage,Wealth:wealthPage,Properties:propertiesPage,Team:teamPage,Commerce:commercePage,Touring:tourPage,Campaigns:marketingPage,Opportunities:opportunitiesPage,Labels:labelPage,Legacy:legacyPage,Saves:savesPage};if(extra[careerTab])return nav+extra[careerTab]();if(careerTab==='Achievements')return nav+achievementsPage();if(careerTab==='Certifications')return nav+certificationsPage();if(careerTab==='Finances')return nav+financeScreen();if(careerTab==='Releases')return nav+catalog();if(careerTab==='Activity')return nav+head('Your career, week by week','Activity.')+`<section class="card">${s.history.map(x=>`<div class="story"><small>WEEK ${x.week}</small>${esc(x.text)}</div>`).join('')}</section>`;return nav+careerProfile()}

const cents=n=>Math.round(n*100)/100;
function initialFinance(week=1){return {version:1,sinceWeek:week,year:Math.floor((week-1)/52)+1,livingRules:3,weeks:0,revenue:0,expenses:0,reserve:0,taxesPaid:0,week:{wages:0,live:0,expenses:0},last:null,lastSettlement:null}}
function migrateFinance(){if(!s.finance)s.finance=initialFinance(s.week);if(s.finance.livingRules!==3){delete s.finance.lifestyle;s.finance.livingRules=3;log('Living-cost charges removed. Career overhead and income taxes still apply.')}}
function operationRate(){return [0,.05,.08,.1,.12,.15,.18][tier(s.fans)]*(1-teamEffect('Accountant')*.002)}
function taxDue(profit){let remaining=Math.max(0,profit),tax=0;for(const [width,rate] of [[15000,0],[35000,.1],[100000,.2],[350000,.3],[500000,.35],[Infinity,.4]]){let slice=Math.min(remaining,width);tax+=slice*rate;remaining-=slice;if(remaining<=0)break}return cents(tax)}
function recordIncome(kind,value){s.finance.week[kind]=cents(s.finance.week[kind]+value)}
function closeFinances(royalties,rate){const f=s.finance,w=f.week,labelCut=artistLabelCut(royalties),labelBusiness=w.labelBusiness||0,labelPayroll=w.labelPayroll||0,albumSales=w.albumSales||0,investment=w.investment||0,overhead=cents((royalties+w.live+albumSales)*rate),revenue=cents(royalties+w.live+w.wages+albumSales+labelBusiness+investment),expenses=cents(w.expenses+overhead+labelCut);if(s.expansion.contract)s.expansion.contract.recovered=(s.expansion.contract.recovered||0)+labelCut;f.weeks++;f.revenue=cents(f.revenue+revenue);f.expenses=cents(f.expenses+expenses);const profit=cents(f.revenue-f.expenses),yearEnd=s.week%52===0,target=yearEnd?taxDue(profit):cents(taxDue(Math.max(0,profit)*52/f.weeks)*f.weeks/52),reserveChange=cents(target-f.reserve);f.reserve=target;changeCash(royalties-overhead-reserveChange-labelCut);const report={week:s.week,revenue,investment,royalties,albumSales,labelBusiness,labelPayroll,labelCut,wages:w.wages,live:w.live,expenses,actionExpenses:w.expenses,overhead,rate,taxReserve:reserveChange,net:cents(revenue-expenses-reserveChange),cash:s.cash,yearEnd,settlement:yearEnd?target:0};if(yearEnd){f.lastSettlement={year:f.year,profit,tax:target,reconciliation:reserveChange};f.taxesPaid=cents(f.taxesPaid+target);f.reserve=0;f.year++;f.weeks=0;f.revenue=0;f.expenses=0}f.week={wages:0,live:0,expenses:0};f.last=report;return report}
function financeRows(r,full=false){const payout=cents(r.royalties+(r.albumSales||0)+(r.labelBusiness||0)-(r.labelPayroll||0)-(r.labelCut||0)-r.overhead-r.taxReserve);return [...(full?[['Taxable revenue including realized investments',money(r.revenue)],['Investment gains, distributions & rent',money(r.investment||0)],['Work, advances & live income',money(r.wages+r.live)],['Action costs','−'+money(r.actionExpenses-(r.labelPayroll||0))]]:[]),['Streaming royalties',money(r.royalties)],['Album downloads',money(r.albumSales||0)],['Label-business receipts',money(r.labelBusiness||0)],['Label payroll','−'+money(r.labelPayroll||0)],['Your label contract share','−'+money(r.labelCut||0)],['Career overhead ('+Math.round(r.rate*100)+'%)','−'+money(r.overhead)],[r.taxReserve<0?'Tax reserve returned':'Tax reserve set aside',(r.taxReserve<0?'+':'−')+money(Math.abs(r.taxReserve))],[full?'Net for the whole week':'Week-close payout',money(full?r.net:payout)],['Spendable cash',money(r.cash)]]}

function financeScreen(){const f=s.finance,rate=operationRate();return head('Money in · Money out','Finances.')+metricRail([['Spendable cash',money(s.cash)],['Tax reserve',money(f.reserve)],['Income tax paid',money(f.taxesPaid)],['Career overhead',Math.round(rate*100)+'%']])+`<section class="card"><h2>Your career operation</h2><p>${tierNames[tier(s.fans)]}: <strong>${Math.round(rate*100)}% of streaming, album download and live revenue</strong> covers management, staff and security. Work shifts are exempt. No music income means no overhead.</p><p class="fine">The rate is set by your fan tier at the start of each week close. Unknown 0% · Emerging 5% · Breakout 8% · Star 10% · Superstar 12% · Global star 15% · Global icon 18%. Recording, releases, features, promotion, industry support and tour costs are separate expenses shown before purchase.</p></section><section class="card"><h2>Taxes · Year ${f.year}</h2>${profileRows([['Tracked revenue this year',money(f.revenue)],['Deductible career expenses',money(f.expenses)],['Taxable profit so far',money(Math.max(0,f.revenue-f.expenses))],['Reserved, not spendable',money(f.reserve)],['Tax paid since tracking began',money(f.taxesPaid)]])}<p>At each week close, we estimate annual profit from your tracked weeks and reserve the proportional tax. The reserve can decrease when earnings fall or expenses rise. At Week 52, actual annual profit determines the final bill; the reserve pays it, with any difference charged or returned.</p><details><summary>View game tax brackets</summary>${profileRows([['First $15,000','0%'],['$15,000–$50,000 portion','10%'],['$50,000–$150,000 portion','20%'],['$150,000–$500,000 portion','30%'],['$500,000–$1 million portion','35%'],['Above $1 million portion','40%']])}<p class="fine">Simplified fictional rules: wages and music earnings are income; career costs are deductible. Each rate applies only to its portion. Existing cash and sandbox grants are not income. Losses offset income within the tracked year; no loss carryforward.</p></details><p class="fine">Tracking began Week ${f.sinceWeek}. Earlier earnings and existing savings are not retroactively taxed. This week’s actions enter the annual totals at week close.</p>${f.lastSettlement?`<div class="highlightbox">Year ${f.lastSettlement.year} settled: ${money(f.lastSettlement.tax)} tax on ${money(Math.max(0,f.lastSettlement.profit))} profit. Paid from the reserve; no duplicate charge.</div>`:''}</section><section class="card"><h2>Last completed week</h2>${f.last?financeRows(f.last,true).map(([k,v])=>`<div class="row"><span>${k}</span><strong>${v}</strong></div>`).join(''):'<p>Advance a month to see the complete breakdown.</p>'}</section>`}

function localSaveKey(){return SANDBOX?'encore-offline-sandbox-v1':'encore-offline-v1'}
async function saveLocal(){if(!saveReady)return;try{localStorage.setItem(localSaveKey(),JSON.stringify({schemaVersion:1,state:s}));lastSaved=JSON.stringify(s);saveStatus('Saved on this device ✓')}catch{saveStatus('Device save failed · retry',true);toast('Storage is unavailable or full. Keep this game open until it saves.')}}
async function bootLocal(){titleVisible=true;renderTitle();try{const raw=localStorage.getItem(localSaveKey());if(raw){const data=JSON.parse(raw);if(data.schemaVersion!==1||!data.state||!Array.isArray(data.state.world)||!Number.isInteger(data.state.week)||!!data.state.sandbox!==SANDBOX)throw Error('This local career could not be read.');s=data.state;migrateCharts();migratePacing();migrateDevelopment();migrateCareerRecords();migrateFinance();migrateChartBook();migrateAchievements()}saveReady=true;render();showTitle();await saveLocal()}catch(e){saveReady=false;titleVisible=false;renderTitle();saveStatus('Local save unavailable',true);$('app').innerHTML='<section class="card"><h2>Cannot open your local career</h2><p>Your stored data has not been replaced. Try the same Safari browser outside private browsing.</p><button class="secondary" onclick="bootLocal()">Retry</button></section>'}}
let offlineReady=false;
function offlineBanner(){return OFFLINE?`<aside class="sandbox-banner"><div><strong>OFFLINE EDITION · ON-DEVICE SAVE</strong><p>Your online career stays separate. Clearing this site’s browser data removes this local save.</p><p id="offline-status">${offlineReady?'Ready for offline play.':'Preparing offline files—stay connected until ready.'}</p><p class="fine">On iPhone: Safari → Share → Add to Home Screen.</p></div><a class="secondary" href="/">Online game</a></aside>`:''}
async function prepareOffline(){if(!OFFLINE||!globalThis.navigator?.serviceWorker)return;try{await navigator.serviceWorker.register('/sw.js');const registration=await navigator.serviceWorker.ready;const worker=registration.active;if(!worker)throw Error('Not ready');const ready=await new Promise((resolve,reject)=>{const channel=new MessageChannel();const timer=setTimeout(()=>reject(Error('Offline check timed out')),15000);channel.port1.onmessage=e=>{clearTimeout(timer);resolve(e.data?.ready===true)};worker.postMessage({type:'CHECK_OFFLINE'},[channel.port2])});if(!ready)throw Error('Files unavailable');offlineReady=true;if($('offline-status'))$('offline-status').textContent='Ready for offline play.'}catch{if($('offline-status'))$('offline-status').textContent='Offline files are not ready. Reopen this page while connected and try again.'}}

function initialChartBook(){return {version:1,sinceWeek:1,issuedWeek:null,songs:{current:[],previous:[],records:{}},albums:{current:[],previous:[],records:{}}}}
function albumStreams(a,lifetime=false){return s.songs.filter(x=>a.tracks.includes(x.id)&&x.released).reduce((n,x)=>n+(lifetime?x.total:x.streams),0)}
function compileSongs(){return widerIndustry().concat(s.world.flatMap(a=>a.catalog.map((x,i)=>({...x,key:'npc:s:'+a.id+':'+(x.uid??i),artist:a.name,tier:tierNames[tier(a.fans)],releaseWeek:x.week})).filter(x=>x.type==='Single')),s.songs.filter(x=>x.released&&x.total>0).map(x=>({...x,key:'you:s:'+x.id,artist:s.name,tier:tierNames[tier(s.fans)],you:true,releaseWeek:x.released}))).filter(x=>x.streams>=CHART_FLOOR).sort((a,b)=>b.streams-a.streams||a.key.localeCompare(b.key)).slice(0,CHART_SIZE)}
function compileAlbums(){const week=s.chartWeek??1;const backdrop=Array.from({length:80},(_,i)=>{let era=Math.floor((week+i%16)/16);return {key:'bg:a:'+i+':'+era,title:titles.album[0][(i+era)%10]+' '+titles.album[1][(Math.floor(i/10)+era)%10],artist:seeds[i%seeds.length][0],releaseWeek:era*16-i%16,background:true,streams:Math.round((1200000+180000000*Math.pow(1-i/80,3))*(.8+.2*Math.sin(week*.4+i))),type:'Album'}});return backdrop.concat(s.world.flatMap(a=>a.catalog.map((x,i)=>({...x,key:'npc:a:'+a.id+':'+(x.uid??i),artist:a.name,releaseWeek:x.week,streams:x.streams+a.catalog.filter(t=>t.albumIndex===i).reduce((n,t)=>n+t.streams,0)})).filter(x=>x.type==='Album')),s.albums.filter(a=>a.week<=week&&(albumStreams(a)>0||a.weeklySales>0)).map(a=>({...a,key:'you:a:'+a.id,artist:s.name,releaseWeek:a.week,streams:albumStreams(a),total:albumStreams(a,true),type:'Album',you:true}))).map(x=>({...x,units:Math.floor(x.streams/1500)+(x.you?(x.weeklySales||0):0)})).filter(x=>x.units>=1000).sort((a,b)=>b.units-a.units||a.key.localeCompare(b.key)).slice(0,50)}
function chart(){return s.chartBook?.issuedWeek!==null&&s.chartBook?.issuedWeek!==undefined?s.chartBook.songs.current:compileSongs()}
function albumChart(){return s.chartBook?.issuedWeek!==null&&s.chartBook?.issuedWeek!==undefined?s.chartBook.albums.current:compileAlbums()}
function chartOwner(kind,id){return (kind==='songs'?s.songs:s.albums).find(x=>x.id===id)}
function chartRecord(kind,key){return s.chartBook?.[kind]?.records[key]??null}
function trackChartIssue(kind,list,baseline=false){const book=s.chartBook,board=book[kind],week=s.chartWeek;board.previous=baseline?[]:board.current;const prior=new Map(board.previous.map((x,i)=>[x.key,i+1]));const present=new Set(list.map(x=>x.key));board.current=list.map((x,i)=>{const rank=i+1,owner=x.you?chartOwner(kind,x.id):null;let record=board.records[x.key];const existed=!!record;let earlier=baseline||(!existed&&x.releaseWeek<book.sinceWeek);if(!record){record=board.records[x.key]={title:x.title,artist:x.artist,you:!!x.you,id:x.id??null,peak:owner?.peak??rank,weeks:baseline?(owner?.chartWeeks||0):owner?.chartWeeks||0,numberOneWeeks:owner?.numberOneWeeks||0,streak:owner?.numberOneStreak||0,longest:owner?.longestNumberOne||0,debutRank:earlier?null:rank,debutWeek:earlier?null:week,partial:earlier,history:[]}}
record.title=x.title;record.artist=x.artist;record.peak=Math.min(record.peak||rank,rank);record.lastSeen=week;record.lastRank=rank;if(!baseline){record.weeks++;record.streak=rank===1?record.streak+1:0;if(rank===1)record.numberOneWeeks++;record.longest=Math.max(record.longest,record.streak)}else record.weeks=Math.max(1,record.weeks);record.history.push({week,rank});record.history=record.history.slice(-104);if(owner){owner.peak=record.peak;owner.chartWeeks=record.weeks;owner.numberOneWeeks=record.numberOneWeeks;owner.numberOneStreak=record.streak;owner.longestNumberOne=record.longest}
const last=prior.get(x.key)??null;return {key:x.key,id:x.id??null,title:x.title,artist:x.artist,you:!!x.you,streams:x.streams,units:x.units??null,rank,last,peak:record.peak,weeks:record.weeks,debutRank:record.debutRank,debutWeek:record.debutWeek,partial:record.partial,movement:baseline?'BASE':last?(last===rank?'HOLD':last>rank?'UP':'DOWN'):existed?'RE':earlier?'ENTRY':'NEW'};});
for(const [key,record] of Object.entries(board.records)){if(!present.has(key)){if(record.lastRank!==null){record.history.push({week,rank:null});record.history=record.history.slice(-104)}record.lastRank=null;record.streak=0;const owner=record.you?chartOwner(kind,record.id):null;if(owner)owner.numberOneStreak=0;if(!record.you&&week-record.lastSeen>104)delete board.records[key]}}
}
function updateChartRecords(rankings){if(!s.chartBook)s.chartBook=initialChartBook();if(s.chartBook.issuedWeek===s.chartWeek)return;trackChartIssue('songs',rankings);trackChartIssue('albums',compileAlbums());s.chartBook.issuedWeek=s.chartWeek;updateCertifications();lateChartAlerts()}
function migrateChartBook(){if(s.chartBook?.version===1)return;s.chartBook=initialChartBook();s.chartBook.sinceWeek=s.week;if(s.week>1){trackChartIssue('songs',compileSongs(),true);trackChartIssue('albums',compileAlbums(),true);s.chartBook.issuedWeek=s.chartWeek}for(const [kind,list] of [['songs',s.songs],['albums',s.albums]])for(const x of list){const key='you:'+(kind==='songs'?'s':'a')+':'+x.id;if((x.peak||x.chartWeeks)&&!s.chartBook[kind].records[key])s.chartBook[kind].records[key]={title:x.title,artist:s.name,you:true,id:x.id,peak:x.peak||null,weeks:x.chartWeeks||0,numberOneWeeks:x.numberOneWeeks||0,streak:0,longest:x.longestNumberOne||0,debutRank:null,debutWeek:null,partial:true,lastRank:null,lastSeen:s.chartWeek,history:[]}}updateCertifications(true)}
function certificationUnits(item,kind){return Math.floor((kind==='albums'?albumStreams(item,true):(item.total||0))/(kind==='albums'?1500:150))+(kind==='albums'?(item.sales||0):0)}
function certificationInfo(units){let milestone=units>=1e6?Math.floor(units/1e6)*1e6:units>=500000?500000:0;let next=milestone<500000?500000:milestone===500000?1e6:milestone+1e6;let tier=units>=1e7?'diamond':units>=2e6?'multi':units>=1e6?'platinum':units>=500000?'gold':'none';let label=tier==='diamond'?'Diamond · '+fmt(Math.floor(units/1e6))+'× Platinum':tier==='multi'?fmt(Math.floor(units/1e6))+'× Platinum':tier==='platinum'?'Platinum':tier==='gold'?'Gold':'Uncertified';return {milestone,next,tier,label,progress:clamp((units-milestone)/(next-milestone)*100)}}
function updateCertifications(recovered=false){for(const [kind,list] of [['songs',s.songs.filter(x=>x.released)],['albums',s.albums]])for(const item of list){const units=certificationUnits(item,kind),info=certificationInfo(units);if(info.milestone>(item.certification?.milestone||0)){item.certification={milestone:info.milestone,label:info.label,tier:info.tier,week:recovered?null:s.week,recovered,history:[...(item.certification?.history||[]),{label:info.label,week:recovered?null:s.week,units}].slice(-30)};if(!recovered){addBriefing('cert:'+kind+':'+item.id+':'+info.milestone,'Celebration',info.label+' certified','“'+item.title+'” reached '+fmt(units)+' equivalent units. Your '+(kind==='songs'?'song':'album')+' earned '+info.label+'.','Your award is saved in Career → Certifications.');log('“'+item.title+'” earned '+info.label+' '+(kind==='songs'?'song':'album')+' certification.')}}}}
function certBadge(item,kind){const c=certificationInfo(certificationUnits(item,kind));return `<span class="cert-badge cert-${c.tier}">${esc(c.label)}</span>`}
function certificationRules(){return `<details class="card cert-rules"><summary>How ENCORE certifications work</summary><p>Automatic game awards based on lifetime streams: 150 song streams = 1 song unit; 1,500 album-track streams = 1 album unit. Gold: 500,000 units. Platinum: 1 million. Multi-Platinum: each million above that. Diamond: 10 million units, with further million-unit milestones.</p><p>Song Gold requires 75 million streams; album Gold requires 750 million combined track streams. Albums include their member tracks’ lifetime streams, including pre-album singles, counted once per album. This adds no streams or royalties to your career total.</p><p class="fine">ENCORE uses worldwide simulated streams and one award system across genres. These are game achievements, not official RIAA certifications, audits or Billboard results.</p></details>`}
function certificationCard(item,kind){const units=certificationUnits(item,kind),c=certificationInfo(units);return `<section class="card certification-card"><div class="sectionhead"><span class="eyebrow">${kind==='songs'?'Song':'Album'}</span>${certBadge(item,kind)}</div><button class="release-link" onclick="releaseDetails('${kind}',${item.id})">${esc(item.title)}</button><p>${fmt(units)} equivalent units · ${compact(kind==='albums'?albumStreams(item,true):item.total)} streams</p><div class="bar"><i style="width:${c.progress}%"></i></div><div class="sectionhead fine"><span>${fmt(c.next-units)} units to next award</span><strong>${c.progress.toFixed(1)}%</strong></div><p class="fine">Next: ${esc(certificationInfo(c.next).label)}${item.certification?'<br>'+ (item.certification.recovered?'Current award recovered from saved totals':'Current award earned Week '+item.certification.week):''}</p></section>`}
function certificationsPage(){const list=certificateFilter==='Albums'?s.albums:s.songs.filter(x=>x.released),kind=certificateFilter==='Albums'?'albums':'songs';return head('Your catalog, recognized','Certifications.')+`<div class="chips">${['Songs','Albums'].map(t=>`<button class="${certificateFilter===t?'selected':''}" onclick="certificateFilter='${t}';render()">${t}</button>`).join('')}</div><div class="certification-grid">${list.length?list.slice().sort((a,b)=>certificationUnits(b,kind)-certificationUnits(a,kind)).map(x=>certificationCard(x,kind)).join(''):'<section class="card empty"><h2>Your first plaque starts with a release.</h2><p>Finish and release music to track its progress here.</p></section>'}</div>`+certificationRules()}
function movementLabel(x){if(x.movement==='NEW')return 'NEW';if(x.movement==='RE')return 'RE-ENTRY';if(x.movement==='ENTRY')return 'ENTRY';if(x.movement==='BASE')return '—';if(x.movement==='HOLD')return '—';return (x.movement==='UP'?'↑ ':'↓ ')+Math.abs(x.last-x.rank)}
function chartHub(){const kind=chartKind==='Albums'?'albums':'songs',list=kind==='songs'?chart():albumChart(),book=s.chartBook,board=book?.[kind],ready=book?.issuedWeek!==null&&book?.issuedWeek!==undefined,visible=chartMine?list.filter(x=>x.you):list,dropouts=ready?board.previous.filter(x=>!board.current.some(y=>y.key===x.key)):[];return head('The weekly issue',kind==='songs'?'Global Top 100.':'Global Albums 50.',`<span class="pill">${ready?'Week '+book.issuedWeek:'Preview'}</span>`)+`<div class="chart-toolbar"><div class="chips">${['Songs','Albums'].map(t=>`<button class="${chartKind===t?'selected':''}" onclick="chartKind='${t}';render()">${t}</button>`).join('')}</div><button class="secondary" aria-pressed="${chartMine}" onclick="chartMine=!chartMine;render()">${chartMine?'Show all artists':'My releases'}</button></div><div class="chart-summary"><div><span>Entries</span><strong>${list.length}</strong></div><div><span>New entries</span><strong>${list.filter(x=>x.movement==='NEW').length}</strong></div><div><span>Your entries</span><strong>${list.filter(x=>x.you).length}</strong></div><div><span>Entry cutoff</span><strong>${compact(list.at(-1)?.[kind==='songs'?'streams':'units']??(kind==='songs'?CHART_FLOOR:1000))}</strong></div></div><p class="fine">${kind==='songs'?'Weekly streams · Minimum 250,000 plays, plus a Top 100 rank.':'Weekly album units · 1,500 track streams = 1 unit. Minimum 1,000 units, plus a Top 50 rank.'} ${ready?'Movement compares the previous completed issue.':'Advance a month to publish the first issue.'}</p><div class="chart-list">${visible.map((x,index)=>`<article class="chart-entry ${x.you?'chart-you':''}"><div class="chart-place">${x.rank??list.indexOf(x)+1}<span class="movement movement-${x.movement||'BASE'}">${ready?movementLabel(x):'—'}</span></div><div class="chart-release"><button class="release-link" onclick="chartDetails('${kind}','${x.key}')">${esc(x.title)}</button><p>${esc(x.artist)}${x.you?' · YOU':''}</p>${x.you&&certificationUnits(chartOwner(kind,x.id),kind)>=500000?certBadge(chartOwner(kind,x.id),kind):''}<div class="chart-facts"><span>Last <b>${x.last?'#'+x.last:'—'}</b></span><span>Peak <b>${x.peak?'#'+x.peak:'—'}</b></span><span>Weeks <b>${x.weeks??'—'}${x.partial?'+':''}</b></span><span>Debut <b>${x.debutRank?'#'+x.debutRank:'—'}</b></span></div></div><div class="chart-volume"><strong>${compact(kind==='songs'?x.streams:x.units)}</strong><span>${kind==='songs'?'streams':'units'}</span></div></article>`).join('')||'<section class="card empty"><h2>No chart entries yet.</h2><p>Your releases need enough weekly activity to beat the competition.</p></section>'}</div>${dropouts.length?`<details class="card"><summary>Dropped out this week · ${dropouts.length}</summary>${dropouts.filter(x=>!chartMine||x.you).map(x=>`<div class="row"><button class="release-link" onclick="chartDetails('${kind}','${x.key}')">${esc(x.title)} · ${esc(x.artist)}</button><span class="fine">Last #${x.rank}</span></div>`).join('')||'<p>No releases of yours dropped out.</p>'}</details>`:''}<p class="fine">NEW = first chart entry. RE-ENTRY = returns after dropping out. ENTRY = first observed during tracking; original debut unknown. + = partial historical week count. Prior issue, debut and movement are unavailable for older data the game never recorded.</p>`}
function chartDetails(kind,key){const rec=chartRecord(kind,key),row=s.chartBook?.[kind].current.find(x=>x.key===key);if(!rec){modal('<h2>First issue pending</h2><p>Advance the month to start recording chart history.</p>');return}if(rec.you){releaseDetails(kind,rec.id);return}modal(`<div class="eyebrow">${kind==='songs'?'Song':'Album'} chart history</div><h2>${esc(rec.title)}</h2><p>${esc(rec.artist)}</p>`+chartRecordDetails(rec,row))}
function chartRecordDetails(rec,row){return profileRows([['Current position',row?'#'+row.rank:'Off chart'],['Last week',row?.last?'#'+row.last:'—'],['Peak',rec.peak?'#'+rec.peak:'Not recorded'],['Chart debut',rec.debutRank?'#'+rec.debutRank+' · Week '+rec.debutWeek:'Not recorded before tracking'],['Weeks charted',rec.weeks+(rec.partial?' (partial history)':'')],['Weeks at #1',rec.numberOneWeeks],['Longest #1 streak',rec.longest+' weeks']])+`<h3 style="margin-top:22px">Recent chart path</h3><div class="chart-path">${rec.history.slice(-12).map(p=>`<div><small>W${p.week}</small><strong>${p.rank?'#'+p.rank:'OUT'}</strong></div>`).join('')}</div><p class="fine">Recent recorded results shown. Full week counts and peak are kept; detailed history retains the latest 104 chart events.</p>`}
function releaseDetails(kind,id){const item=chartOwner(kind,id);if(!item)return;const key='you:'+(kind==='songs'?'s':'a')+':'+id,rec=chartRecord(kind,key),row=s.chartBook?.[kind].current.find(x=>x.key===key),units=certificationUnits(item,kind);modal(`<div class="eyebrow">${kind==='songs'?'Song':'Album'} · Released Week ${kind==='songs'?item.released:item.week}</div><h2>${esc(item.title)}</h2>${certBadge(item,kind)}${profileRows([['Lifetime streams',fmt(kind==='albums'?albumStreams(item,true):item.total)],['Certification units',fmt(units)],...(kind==='albums'?[['Album cohesion',(item.cohesion??'Not tracked')+'/100'],['Critical reception',(item.criticalReception??'Not tracked')+'/100']]:[['Lifecycle',item.lifecycle||'Awaiting debut'],['Genre fit this week',item.marketFit?item.marketFit+'%':'Pending']]),['Release debut streams',item.debutStreams!==undefined?fmt(item.debutStreams):'Not recorded / pending']])}${rec?chartRecordDetails(rec,row):'<p>No recorded chart entry yet.</p>'}${kind==='songs'?`<p class="fine">Quality ${item.quality}/100 · Commercial potential ${item.commercial??'—'}/100</p>`:''}${item.certification?`<h3>Award history</h3>${item.certification.history.map(h=>`<div class="row"><span>${esc(h.label)}</span><span class="fine">${h.week?'Week '+h.week:'Recovered from saved streams'}</span></div>`).join('')}`:'<p class="fine">Gold is the first certification at 500,000 equivalent units.</p>'}`)}

function initialAchievements(){return {version:1,unlocked:{},briefings:[],popups:true}}
function achievementDefinitions(){return [
{id:'first_lesson',title:'Find your voice',description:'Raise any development stat to level 1.',target:1,value:Math.max(...Object.values(s.development).map(x=>x.level)),group:'Development'},
{id:'craft25',title:'Putting in the work',description:'Reach level 25 in any development stat.',target:25,value:Math.max(...Object.values(s.development).map(x=>x.level)),group:'Development'},
{id:'mastery',title:'Generational talent',description:'Reach level 100 in any development stat.',target:100,value:Math.max(...Object.values(s.development).map(x=>x.level)),group:'Development'},
{id:'first_song',title:'The first record',description:'Release your first song.',target:1,value:s.songs.filter(x=>x.released).length,group:'Releases'},
{id:'ten_songs',title:'A catalog of your own',description:'Release ten songs.',target:10,value:s.songs.filter(x=>x.released).length,group:'Releases'},
{id:'first_album',title:'Your first era',description:'Release your first album.',target:1,value:s.albums.length,group:'Releases'},
{id:'feature',title:'Better together',description:'Release a song with a guest artist.',target:1,value:s.songs.filter(x=>x.released&&x.feature).length,group:'Releases'},
{id:'fans100',title:'The first hundred',description:'Build an audience of 100 true fans.',target:100,value:s.fans,group:'Audience'},
{id:'fans1k',title:'They know your name',description:'Reach 1,000 true fans.',target:1000,value:s.fans,group:'Audience'},
{id:'fans1m',title:'A million believers',description:'Reach one million true fans.',target:1e6,value:s.fans,group:'Audience'},
{id:'fans100m',title:'Global icon',description:'Reach 100 million true fans.',target:1e8,value:s.fans,group:'Audience'},
{id:'streams1m',title:'On repeat',description:'Earn one million lifetime streams.',target:1e6,value:s.total,group:'Audience'},
{id:'streams1b',title:'The billion club',description:'Earn one billion lifetime streams.',target:1e9,value:s.total,group:'Audience'},
{id:'chart',title:'On the board',description:'Land a song on the Global Top 100.',target:1,value:s.songs.filter(x=>x.peak).length,group:'Charts'},
{id:'song1',title:'Top of the world',description:'Reach number one on the song chart.',target:1,value:s.songs.filter(x=>x.peak===1).length,group:'Charts'},
{id:'album1',title:'An era at number one',description:'Reach number one on the album chart.',target:1,value:s.albums.filter(x=>x.peak===1).length,group:'Charts'},
{id:'gold',title:'Worth its weight',description:'Earn a Gold or higher song or album award.',target:500000,value:Math.max(0,...s.songs.filter(x=>x.released).map(x=>certificationUnits(x,'songs')),...s.albums.map(x=>certificationUnits(x,'albums'))),group:'Awards'},
{id:'platinum',title:'Platinum status',description:'Earn a Platinum or higher award.',target:1e6,value:Math.max(0,...s.songs.filter(x=>x.released).map(x=>certificationUnits(x,'songs')),...s.albums.map(x=>certificationUnits(x,'albums'))),group:'Awards'},
{id:'diamond',title:'Pressure made a diamond',description:'Earn a Diamond award.',target:1e7,value:Math.max(0,...s.songs.filter(x=>x.released).map(x=>certificationUnits(x,'songs')),...s.albums.map(x=>certificationUnits(x,'albums'))),group:'Awards'},
{id:'openmic',title:'Take the stage',description:'Perform your first open mic.',target:1,value:s.careerRecords.openMics,group:'Live'},
{id:'tour',title:'On the road',description:'Complete your first local run.',target:1,value:s.careerRecords.tours.length,group:'Live'}]}
function addBriefing(id,type,title,body,detail=''){if(!s.achievements)s.achievements=initialAchievements();if(s.achievements.briefings.some(x=>x.id===id))return;s.achievements.briefings.unshift({id,type,title,body,detail,week:s.week,read:id.startsWith('cert:')});s.achievements.briefings=s.achievements.briefings.slice(0,80)}
function scanAchievements(recovered=false){if(!s.achievements)s.achievements=initialAchievements();if(s.achievements.baselinePending){delete s.achievements.baselinePending;recovered=true}const earned=[];for(const a of achievementDefinitions()){if(a.value>=a.target&&!s.achievements.unlocked[a.id]){s.achievements.unlocked[a.id]={week:recovered?null:s.week,recovered};earned.push(a)}}if(earned.length&&!recovered)addBriefing('ach:'+earned.map(x=>x.id).join('-'),'Achievement',earned.length===1?earned[0].title:earned.length+' milestones unlocked',earned.map(x=>x.title+' — '+x.description).join('\n'),'Saved permanently in your achievement collection.');return earned}
function migrateAchievements(){if(s.achievements?.version===1)return;s.achievements=initialAchievements();scanAchievements(true)}
let briefingTimer;
function scheduleBriefing(){clearTimeout(briefingTimer);if(!saveReady||saveConflict||!s.achievements?.popups)return;briefingTimer=setTimeout(()=>{if(!titleVisible&&tourStep<0&&!$('modal').open){const next=s.achievements.briefings.find(x=>!x.read&&!x.id.startsWith('cert:'));if(next)showBriefing(next.id)}},120)}
function memoFrame(type,title,body,footer='',issueWeek=s.week){return `<article class="artist-memo"><div class="memo-tab">${esc(type)}</div><div class="memo-brand">ENCORE</div><div class="memo-subtitle">ARTIST RELATIONS · PRIVATE BRIEFING</div><dl class="memo-address"><div><dt>TO</dt><dd>${esc(s.name)}</dd></div><div><dt>FROM</dt><dd>${type==='Industry news'?'Industry Desk':type==='Weekly recap'?'Your Career Team':'Artist Relations'}</dd></div><div><dt>DATE</dt><dd>${careerDate(calendarMonthAtWeek(issueWeek))}</dd></div></dl><h2>${esc(title)}</h2>${body}<div class="memo-signoff">Your next chapter starts here.<strong>The ENCORE Team</strong></div>${footer}</article>`}
function showBriefing(id){if(!saveReady||saveConflict)return;const b=s.achievements?.briefings.find(x=>x.id===id);if(!b)return;b.read=true;modal(memoFrame(b.type,b.title,`<span class="memo-stamp">${esc(b.type==='Achievement'?'UNLOCKED':b.type==='Celebration'?'MILESTONE':'BRIEFED')}</span><p class="memo-copy">${b.id.startsWith('catalog:')?esc(b.body.split('\n\n')[0])+'</p><details><summary>All release records</summary><p class="memo-copy">'+esc(b.body.split('\n\n').slice(1).join('\n\n')).replaceAll('\n','<br>')+'</p></details><p>':esc(b.body).replaceAll('\n','<br><br>')}</p>${b.detail?`<p class="memo-note">${esc(b.detail)}</p>`:''}<p class="memo-note">Filed Week ${b.week}</p>`,`${offerBriefingButton(b)}<button class="memo-primary" onclick="$('modal').close()">Continue career</button><button class="memo-secondary" onclick="$('modal').close();careerTab='Achievements';go('Career')">View achievements & briefings</button>`,b.week),'memo-dialog');queueSave()}
function catalogReport(completed){
const tracks=s.songs.filter(x=>x.released);if(!tracks.length)return;
for(const t of tracks){t.reportStreams=(t.reportStreams||[]).filter(x=>x.week>completed-4&&x.week!==completed);t.reportStreams.push({week:completed,streams:t.streams||0})}
if(completed%4!==0)return;
const from=completed-3,ranked=tracks.map(t=>({track:t,streams:t.reportStreams.filter(x=>x.week>=from).reduce((n,x)=>n+x.streams,0)})).sort((a,b)=>b.streams-a.streams);
const observed=Math.min(...tracks.flatMap(t=>t.reportStreams.map(x=>x.week))),top=ranked[0],total=ranked.reduce((n,x)=>n+x.streams,0);
const songLines=ranked.map(({track:t,streams})=>'“'+t.title+'” — '+compact(streams)+' streams · '+(chartPosition(t)?'Chart #'+chartPosition(t):'Uncharted')+(t.certification?' · '+t.certification.label:''));
const albumLines=s.albums.map(a=>{const streams=ranked.filter(x=>a.tracks.includes(x.track.id)).reduce((n,x)=>n+x.streams,0);return '“'+a.title+'” — '+compact(streams)+' track streams'+(a.certification?' · '+a.certification.label:'')});
const awards=[...tracks,...s.albums].flatMap(t=>(t.certification?.history||[]).filter(x=>x.week!==null&&x.week>=from&&x.week<=completed).map(x=>'“'+t.title+'” — '+x.label));
addBriefing('catalog:'+completed,'Music report','Your music · Weeks '+from+'–'+completed,
'Total song streams: '+compact(total)+'\nBiggest song: “'+top.track.title+'” · '+compact(top.streams)+' streams\n\nSONGS\n'+songLines.join('\n')+(albumLines.length?'\n\nALBUMS\n'+albumLines.join('\n'):'')+(awards.length?'\n\nNEW CERTIFICATIONS\n'+awards.join('\n'):''),
(observed>from?'Stream tracking started Week '+observed+'; earlier weeks are not included. ':'')+'Album streams are included in the song total, not added twice. Chart positions and awards are current at the end of Week '+completed+'. Your next music report arrives in four weeks.');
}
function weeklyNews(completed){const releases=s.feed.filter(x=>x.week===completed).sort((a,b)=>b.streams-a.streams);if(!releases.length)return;const lead=releases[0];addBriefing('news:'+completed,'Industry news',lead.name+' leads the release desk','“'+lead.title+'” arrived with '+compact(lead.streams)+' debut streams. '+(releases.length>1?(releases.length-1)+' other projects dropped this week.':'It was the week’s new industry release.'),'Open Industry → New releases to see who you are competing with.')}
function achievementsPage(){const defs=achievementDefinitions(),unlocked=Object.keys(s.achievements.unlocked).length,visible=defs.filter(a=>achievementFilter==='All'||(achievementFilter==='Unlocked'?!!s.achievements.unlocked[a.id]:!s.achievements.unlocked[a.id]));return head('The story you are building','Achievements.',`<span class="pill">${unlocked} / ${defs.length}</span>`)+`<div class="achievement-controls"><div class="chips">${['All','Unlocked','Locked'].map(t=>`<button class="${achievementFilter===t?'selected':''}" onclick="achievementFilter='${t}';render()">${t}</button>`).join('')}</div><button class="secondary" aria-pressed="${s.achievements.popups}" onclick="toggleBriefings()">Pop-ups: ${s.achievements.popups?'On':'Off'}</button></div><div class="achievement-stack">${visible.map(a=>{const earned=s.achievements.unlocked[a.id];return `<section class="card achievement-card ${earned?'earned':''}"><span class="achievement-mark">${earned?'✓':'○'}</span><div><span class="eyebrow">${esc(a.group)}</span><h2>${esc(a.title)}</h2><p>${esc(a.description)}</p><div class="bar"><i style="width:${earned?100:clamp(a.value/a.target*100)}%"></i></div><span class="fine">${earned?(earned.recovered?'Recovered from saved career · Original date unknown':'Unlocked Week '+earned.week):compact(Math.min(a.value,a.target))+' / '+compact(a.target)}</span></div></section>`}).join('')||'<section class="card"><p>No achievements in this view yet.</p></section>'}</div><section class="card"><div class="sectionhead"><h2>Briefing archive</h2><button class="secondary" onclick="readAllBriefings()">Mark all read</button></div><p class="fine">News, celebrations and milestones. Latest 80 briefings are kept; unlocked achievements are permanent.</p>${s.achievements.briefings.map(b=>`<button class="briefing-row" onclick="showBriefing('${b.id}')"><span><small>${esc(b.type)} · Week ${b.week}${b.read?'':' · NEW'}</small><strong>${esc(b.title)}</strong></span><span>Open</span></button>`).join('')||'<p>Your news and milestone letters will appear here.</p>'}</section>`}
function toggleBriefings(){if(!saveReady||saveConflict)return;s.achievements.popups=!s.achievements.popups;render()}
function readAllBriefings(){if(!saveReady||saveConflict)return;s.achievements.briefings.forEach(b=>b.read=true);render()}
function briefingShortcut(){const unread=s.achievements.briefings.filter(x=>!x.read&&!x.id.startsWith('cert:')).length;return `<button class="briefing-shortcut" onclick="careerTab='Achievements';go('Career')"><span><strong>Your achievements & briefings</strong><small>${Object.keys(s.achievements.unlocked).length} milestones unlocked${unread?' · '+unread+' unread':''}</small></span><span>Open</span></button>`}
function weekRecap(completed,count,added,debut,financial,earned=[]){const top=debut.slice().sort((a,b)=>b.streams-a.streams)[0];modal(memoFrame('Weekly recap','Week '+completed+' · Your career report',`<div class="memo-headline"><span>Streams this week</span><strong>${compact(count)}</strong><small>${added>=0?'+':''}${compact(added)} net fans</small></div><div class="memo-finances">${financeRows(financial).map(([k,v])=>`<div><span>${esc(k)}</span><strong>${esc(v)}</strong></div>`).join('')}</div>${earned.length?`<p class="memo-note">${earned.length} new achievements filed.</p>`:''}${financial.yearEnd?`<p class="memo-note">Tax year settled: ${money(financial.settlement)} paid from your reserve.</p>`:''}<p class="memo-note">Energy restored to 200. ${s.feed.filter(x=>x.week===completed).length} industry projects released.</p>`,`<button class="memo-primary" onclick="$('modal').close()">Start week ${s.week}</button><button class="memo-secondary" onclick="$('modal').close();careerTab='Finances';go('Career')">Full financial report</button>`,completed),'memo-dialog');queueSave()}
$('modal').addEventListener?.('close',()=>{ if(!$('modal').open){$('modal').className='';scheduleBriefing()}});


